'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var dbraycurtis = require( './../lib/ndarray.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dbraycurtis, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 7', function test( t ) {
	t.strictEqual( dbraycurtis.length, 7, 'returns expected value' );
	t.end();
});

tape( 'the function calculates the Bray-Curtis distance between two strided arrays', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array( [ 4.0, 2.0, -3.0, 5.0, -1.0, 2.0, -5.0, 6.0 ] );
	y = new Float64Array( [ 2.0, 6.0, -1.0, -4.0, 8.0, 8.0, 2.0, -3.0 ] );

	// Test against textbook formula: (2+4+2+9+9+6+7+9)/(6+8+4+1+7+10+3+3) = 48/42 = 1.1428571428571428
	d = dbraycurtis( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( isAlmostSameValue( d, 1.1428571428571428, 1e-12 ), true, 'returns expected value' );

	x = new Float64Array( [ 3.0, -4.0, 1.0 ] );
	y = new Float64Array( [ 1.0, -2.0, 3.0 ] );

	// Test against textbook formula: (2+2+2)/(4+6+4) = 6/14 = 0.42857142857142855
	d = dbraycurtis( x.length, x, 1, 0, y, 1, 0 );
	t.strictEqual( isAlmostSameValue( d, 0.42857142857142855, 1e-12 ), true, 'returns expected value' );

	t.end();
});

tape( 'if provided an `N` parameter less than or equal to `0`, the function returns `NaN`', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array( [ 3.0, -4.0, 1.0 ] );
	y = new Float64Array( [ 1.0, -2.0, 3.0 ] );

	d = dbraycurtis( 0, x, 1, 0, y, 1, 0 );
	t.strictEqual( isAlmostSameValue( d, NaN, 0 ), true, 'returns expected value' );

	d = dbraycurtis( -4, x, 1, 0, y, 1, 0 );
	t.strictEqual( isAlmostSameValue( d, NaN, 0 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports an `x` stride', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array([
		2.0,  // 0
		-3.0,
		-5.0, // 1
		7.0,
		6.0   // 2
	]);
	y = new Float64Array([
		8.0,  // 0
		2.0,  // 1
		-3.0, // 2
		3.0,
		-4.0,
		1.0
	]);

	// Test against textbook formula: (6+7+9)/(10+3+3) = 22/16 = 1.375
	d = dbraycurtis( 3, x, 2, 0, y, 1, 0 );
	t.strictEqual( isAlmostSameValue( d, 1.375, 1e-12 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports an `x` offset', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array([
		1.0,
		2.0, // 0
		3.0,
		4.0, // 1
		5.0,
		6.0  // 2
	]);
	y = new Float64Array([
		6.0,  // 0
		7.0,  // 1
		8.0,  // 2
		9.0,
		10.0,
		11.0
	]);

	// Test against textbook formula: (4+3+2)/(8+11+14) = 9/33 = 0.272727272727272
	d = dbraycurtis( 3, x, 2, 1, y, 1, 0 );
	t.strictEqual( isAlmostSameValue( d, 0.2727272727272727, 1e-12 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports a `y` stride', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array([
		2.0,  // 0
		-3.0, // 1
		-5.0, // 2
		7.0,
		6.0
	]);
	y = new Float64Array([
		8.0,  // 0
		2.0,
		-3.0, // 1
		3.0,
		-4.0, // 2
		1.0
	]);

	// Test against textbook formula: (6+0+1)/(10+6+9) = 7/25 = 0.28
	d = dbraycurtis( 3, x, 1, 0, y, 2, 0 );
	t.strictEqual( isAlmostSameValue( d, 0.28, 1e-12 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports a `y` offset', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array([
		1.0, // 0
		2.0,
		3.0, // 1
		4.0,
		5.0, // 2
		6.0
	]);
	y = new Float64Array([
		6.0,
		7.0,
		8.0,
		9.0,  // 0
		10.0, // 1
		11.0  // 2
	]);

	// Test against textbook formula: (8+7+6)/(10+13+16) = 21/39 = 0.5384615384615384
	d = dbraycurtis( 3, x, 2, 0, y, 1, 3 );
	t.strictEqual( isAlmostSameValue( d, 0.5384615384615384, 1e-12 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports negative strides', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array([
		1.0, // 2
		2.0,
		3.0, // 1
		4.0,
		5.0  // 0
	]);
	y = new Float64Array([
		6.0, // 2
		7.0, // 1
		8.0, // 0
		9.0,
		10.0
	]);

	// Test against textbook formula: (3+4+5)/(13+10+7) = 12/30 = 0.4
	d = dbraycurtis( 3, x, -2, x.length-1, y, -1, 2 );
	t.strictEqual( isAlmostSameValue( d, 0.4, 1e-12 ), true, 'returns expected value' );
	t.end();
});

tape( 'the function supports complex access patterns', function test( t ) {
	var d;
	var x;
	var y;

	x = new Float64Array([
		1.0, // 0
		2.0,
		3.0, // 1
		4.0,
		5.0  // 2
	]);
	y = new Float64Array([
		6.0,
		7.0, // 2
		8.0, // 1
		9.0, // 0
		10.0
	]);

	// Test against textbook formula: (7+4+1)/(13+10+7) = 12/34 = 0.45454545454545453
	d = dbraycurtis( 3, x, 2, 0, y, -1, y.length-2 );
	t.strictEqual( isAlmostSameValue( d, 0.45454545454545453, 1e-12 ), true, 'returns expected value' );
	t.end();
});
